<template><div class="video-hub"><PageHero title="红色影像馆" subtitle="本地图文动态微课、官方公开资源入口与完整讲解稿组成的安全影像专区。" image="/assets/images/party-history/info-overview-video-hub.jpg" eyebrow="项目自制影像馆导览图"/><main class="page"><el-alert title="版权与播放说明" description="当前微课由专题对应的本地图片、字幕和讲解稿组成，不盗链第三方视频；画面逐幅标明媒体性质，没有媒体文件时使用可暂停的项目自制图解，不显示黑色空播放器。" type="info" :closable="false" show-icon/><section class="video-feature reveal"><MotionStory :title="featured.title" :frames="featured.frames" :captions="featured.frameCaptions" :frame-types="featured.frameTypes"/><div><span>{{ featured.category }} · {{ featured.duration }}</span><h2>{{ featured.title }}</h2><p>{{ featured.summary }}</p><RouterLink :to="`/videos/${featured.slug}`">进入完整微课</RouterLink></div></section><div class="video-filter"><button v-for="cat in categories" :key="cat" :class="{active:cat===active}" @click="active=cat">{{ cat }}</button></div><section class="video-grid"><RouterLink v-for="lesson in filtered" :key="lesson.slug" :to="`/videos/${lesson.slug}`" class="video-card reveal"><SafeImage :src="lesson.cover" :alt="`${lesson.title}：${lesson.frameCaptions[0]}`"/><i>▶</i><div><span>{{ lesson.category }} · {{ lesson.duration }} · {{ lesson.frameTypes[0] }}</span><h3>{{ lesson.title }}</h3><p>{{ lesson.summary }}</p></div></RouterLink></section></main></div></template>
<script setup>import{computed,ref}from'vue';import{RouterLink}from'vue-router';import PageHero from'../components/PageHero.vue';import MotionStory from'../components/MotionStory.vue';import SafeImage from'../components/SafeImage.vue';import{videoLessons}from'../data/experienceContent';const featured=videoLessons[0];const active=ref('全部');const categories=['全部',...new Set(videoLessons.map(i=>i.category))];const filtered=computed(()=>active.value==='全部'?videoLessons:videoLessons.filter(i=>i.category===active.value))</script>
<style scoped>.video-hub{background:linear-gradient(180deg,#fffaf0,#f3e7d2)}.video-feature{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(280px,.7fr);gap:26px;align-items:center;margin:30px 0 50px}.video-feature .motion-story{min-height:430px}.video-feature h2{font-size:clamp(30px,4vw,48px);color:var(--red-dark)}.video-feature p{line-height:1.9;color:var(--muted)}.video-feature a{display:inline-flex;padding:12px 18px;color:#fff;background:var(--red);border-radius:8px}.video-filter{display:flex;gap:8px;overflow-x:auto;margin-bottom:24px}.video-filter button{flex:0 0 auto;padding:9px 14px;border:1px solid var(--line);border-radius:999px;background:#fff;cursor:pointer}.video-filter button.active{color:#fff;background:var(--red)}.video-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.video-card{position:relative;overflow:hidden;background:#2b1014;border-radius:12px;color:#fff8e6}.video-card :deep(.safe-image){height:220px}.video-card>i{position:absolute;top:86px;left:calc(50% - 25px);display:grid;place-items:center;width:50px;height:50px;border-radius:50%;background:rgba(143,29,34,.88);font-style:normal;transition:transform .2s}.video-card:hover>i{transform:scale(1.16)}.video-card>div{padding:18px}.video-card span{color:var(--gold-soft);font-size:13px}.video-card h3{font-size:21px}.video-card p{line-height:1.7;color:#e7dccc}@media(max-width:900px){.video-feature{grid-template-columns:1fr}.video-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.video-grid{grid-template-columns:1fr}}</style>
